import {actionDescription,actionForecast,basicRange,guardAmount,rangeHint} from './action-info.mjs';
import {CombatDirector} from './combat.js';
import {MOVES,FOES,BASIC,HEROES,REGIONS,newRun,enemyPlan,distance,migrate,unavailable,act,reward,buy,next,enterBattle,tributeValue} from './engine.mjs';

const app=document.querySelector('#app');
const KEY='arena-heir-v1';
const director=new CombatDirector(()=>sound);
let state=null,screen='start',chosenHero='miri',replaceMode=false,sound=true,busy=false,ctx,saved;

try{saved=JSON.parse(localStorage.getItem(KEY));if(!saved||!Number.isInteger(saved.round)||saved.round<0||saved.round>6||!Array.isArray(saved.moves)||saved.moves.some(move=>!MOVES[move])||!['battle','map','reward','camp','won','lost'].includes(saved.stage)||!Number.isFinite(saved.hp))saved=null;else migrate(saved);}catch{saved=null;}

const esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const hero=()=>HEROES[state?.hero||chosenHero];
const equipmentStyle=round=>`background-position:${round%4*33.333}% ${Math.floor(round%12/4)*50}%`;

function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saved=structuredClone(state);}catch{}}
function tone(win=false){if(!sound)return;try{ctx??=new AudioContext();ctx.resume();const oscillator=ctx.createOscillator(),gain=ctx.createGain();oscillator.connect(gain);gain.connect(ctx.destination);oscillator.type='triangle';oscillator.frequency.setValueAtTime(win?440:180,ctx.currentTime);oscillator.frequency.exponentialRampToValueAtTime(win?880:90,ctx.currentTime+.15);gain.gain.setValueAtTime(.06,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.22);oscillator.start();oscillator.stop(ctx.currentTime+.23);}catch{}}

function header(){return `<header class="story-header"><button class="brand brand-button" data-do="home" aria-label="Arena Heir home">ARENA <span>HEIR</span><small>CROWN OF ECHOES</small></button><div class="tools"><button class="quiet" data-do="help">How to play</button><button class="quiet" data-do="sound" aria-pressed="${sound}">Sound ${sound?'on':'off'}</button>${state?'<button class="quiet" data-do="exit">Save & exit</button>':''}</div></header>`;}

function render(){director.dispose();app.innerHTML=`<div class="wrap illustrated-game">${header()}${screen==='start'?startScreen():screen==='choose'?chooseScreen():state.stage==='map'?mapScreen():state.stage==='battle'?battleScreen():state.stage==='reward'?rewardScreen():state.stage==='camp'?caravanScreen():endScreen()}<div class="footerline"><span>Free to play · Progress saves on this device</span><span>An original illustrated adventure</span></div></div>`;if(state?.stage==='battle')director.mount();}

function startScreen(){return `<section class="storybook-opening"><div class="opening-copy"><span class="chapter-kicker">A hand-painted roguelite adventure</span><h1>The Crown remembers every champion.</h1><p>Cross the arena roads. Defeat their guardians. Take gold, claim their gear—or steal the move that made them famous.</p><button class="primary story-cta" data-do="choose">Choose your heir</button>${saved&&!['won','lost'].includes(saved.stage)?'<button class="quiet continue" data-do="resume">Continue journey</button>':''}</div><div class="opening-seal" aria-hidden="true">✦<small>THE CROWN<br>IS CALLING</small></div></section>`;}

function chooseScreen(){return `<section class="hero-select"><div class="select-heading"><span class="chapter-kicker">Chapter I · The Crownless Road</span><h1>Choose the heir who answers.</h1><p>Every hero can learn rival abilities. Their starting rhythm is different.</p></div><div class="hero-grid">${Object.entries(HEROES).map(([id,item])=>`<button class="hero-card ${chosenHero===id?'selected':''}" data-hero="${id}" style="--hero:${item.color}"><div class="hero-card-art hero-${id}" aria-hidden="true"></div><span class="hero-role">${esc(item.title)}</span><strong>${esc(item.name)}</strong><p>${esc(item.desc)}</p><span class="innate">Innate · ${esc(item.innate)}</span></button>`).join('')}</div><div class="name-panel"><label>Your hero's name <input id="name" maxlength="18" value="${esc(saved?.name||hero().name.split(' ')[0])}" autocomplete="off"></label><button class="primary" data-do="begin">Open the map →</button></div></section>`;}

function currentRegion(){return REGIONS.find(region=>region.rounds.includes(state.round))||REGIONS.at(-1);}
function mapScreen(){const region=currentRegion(),positions=[[18,72],[38,55],[59,69],[80,42],[24,34],[51,25],[79,16]];return `<section class="world-screen"><div class="map-copy"><span class="chapter-kicker">${state.laurels} of 2 Laurels recovered</span><h1>${esc(region.name)}</h1><p>${esc(region.subtitle)}. Choose the glowing crest to continue.</p></div><div class="painted-map" aria-label="Journey map">${FOES.map((foe,index)=>{const [x,y]=positions[index],status=index<state.round?'cleared':index===state.round?'current':'locked',master=[3,6].includes(index);return `<button class="map-node ${status} ${master?'master':''}" style="--x:${x}%;--y:${y}%" data-do="fight" ${status!=='current'?'disabled':''} aria-label="${status==='cleared'?'Defeated':status==='locked'?'Locked':'Fight'} ${esc(foe.name)}"><span>${master?'♛':index<state.round?'✓':'⚔'}</span><strong>${esc(master?'MASTER':foe.name.split(' ')[0])}</strong></button>`;}).join('')}<div class="map-hero hero-${state.hero}" style="--x:${positions[state.round][0]}%;--y:${positions[state.round][1]}%" aria-hidden="true"></div></div><div class="journey-strip"><div><b>${esc(state.name)}</b><span>${esc(hero().title)}</span></div><div><b>${state.gold}</b><span>coins</span></div><div><b>${state.moves.length}/3</b><span>Echoes</span></div><div><b>${state.gear.length}</b><span>Trophies</span></div></div></section>`;}

function fighter(enemy){const foe=FOES[state.round],hp=enemy?state.foeHp:state.hp,max=enemy?foe.hp:state.maxHp,art=enemy?'rival':`hero-${state.hero}`,gearRound=Number(state.equipped?.split('-').at(-1));return `<div class="fighter ${enemy?'enemy':'player'}" style="--tile:${enemy?state.enemyPos:state.playerPos}"><div class="fighter-info"><div class="name-row"><span>${esc(enemy?foe.name:state.name)}</span><span>${hp}/${max}</span></div><div class="health" role="progressbar" aria-label="${enemy?'Rival':'Your'} health" aria-valuenow="${hp}" aria-valuemin="0" aria-valuemax="${max}"><div style="width:${hp/max*100}%"></div></div><div class="stats">${enemy?`${foe.title} · ${foe.armor} armor`:`${hero().innate} · ${state.equipped?'Trophy equipped':'Roadworn gear'}`}</div></div><div class="actor" data-side="${enemy?'enemy':'player'}"><div class="actor-shadow"></div><div class="sprite-facing"><div class="combat-sprite sprite-sheet ${art} rival-${state.round}" aria-hidden="true"></div></div>${!enemy&&state.equipped?`<span class="fighter-trophy equipment-icon" style="${equipmentStyle(gearRound)}" aria-hidden="true"></span>`:''}</div></div>`;}

function intentText(){const [type,amount]=enemyPlan(state);return type==='approach'?['Closing the gap','Your rival will move up to 2 spaces.']:type==='attack'?['Incoming strike',`${amount} damage before armor.`]:type==='guard'?['Guarding',`Blocks ${amount} damage per hit.`]:type==='charge'?['Winding up','A heavy blow lands next turn.']:type==='double'?['Twin strike',`Two hits of ${amount}.`]:type==='drain'?['Life drain',`${amount} damage and possible healing.`]:['Poisoned blade',`${amount} damage and lingering poison.`];}
const shortNames={attack:'Strike',power:'Crush',guard:'Block',dodge:'Dodge',forward:'Leap in',back:'Leap back',rest:'Breathe'};

function actionButton(id,item){const why=unavailable(state,id),description=BASIC[id]?actionDescription(state,id):item.desc,preview=why||actionForecast(state,id),cost=BASIC[id]?.cost||0,damage=preview.match(/^(\d+) damage/);return `<button class="duel-action action-${id} ${MOVES[id]?'special':''}" data-action="${id}" data-preview="${esc(description+' '+preview)}" aria-label="${esc((shortNames[id]||item.name)+'. '+description+' '+preview)}" ${why?'disabled':''}><span class="action-icon" aria-hidden="true">${item.icon}</span><strong>${shortNames[id]||item.name}</strong><small>${why||(damage?`${damage[1]} damage`:id==='guard'?`Block ${guardAmount(state)}`:id==='dodge'?'Evade + counter':id==='rest'?'+3 energy':preview.match(/Take \d+/)?.[0]||'No hit')}</small><span class="action-cost">${cost?`${cost} ⚡`:MOVES[id]?`${MOVES[id].cd}T`:'FREE'}</span></button>`;}

function battleScreen(){const [intentTitle,intentDetail]=intentText();return `<div class="battle-shell illustrated-battle"><div class="duel-ribbon"><h1>${esc(currentRegion().name)}</h1><span>${[3,6].includes(state.round)?'MASTER DUEL':`ROAD DUEL ${state.round+1}`}</span><strong>${state.gold} coins</strong></div><section class="arena painted-arena" aria-label="Illustrated battle arena" data-round="${state.round}">${fighter(false)}${fighter(true)}<div class="rival-intent"><span>NEXT MOVE</span><strong>${intentTitle}</strong><small>${intentDetail}</small></div><div class="combat-caption" role="status" aria-live="polite"></div><div class="combat-fx" aria-hidden="true"></div><div class="arena-distance">${distance(state)<=basicRange(state)?'IN REACH':`${distance(state)} spaces apart`}</div></section><div class="duel-dock"><div class="duel-turn"><strong>${state.bonus?`NEXT HIT +${state.bonus}`:'YOUR MOVE'}</strong><span>Turn ${state.turn+1}</span><div class="duel-energy"><span>Crown spark <b id="energy-value">${state.energy}</b>/6</span><span class="energy-pips" aria-hidden="true">${Array.from({length:6},(_,index)=>`<i class="${index<state.energy?'lit':''}"></i>`).join('')}</span></div></div><div class="actions duel-controls">${Object.entries(BASIC).map(([id,item])=>actionButton(id,item)).join('')}</div>${state.moves.length?`<div class="actions claimed-controls">${state.moves.map(id=>actionButton(id,MOVES[id])).join('')}</div>`:''}<p class="move-preview" id="move-preview">${rangeHint(state)}</p><details class="combat-history"><summary>${esc(state.log.at(-1)||'Battle log')}</summary><div class="log">${state.log.map(line=>`<div>${esc(line)}</div>`).join('')}</div></details></div></div>`;}

function rewardScreen(){const foe=FOES[state.round],move=MOVES[foe.move],master=[3,6].includes(state.round);return `<section class="reward-story"><div class="defeated-card"><span class="chapter-kicker">${master?'MASTER FALLEN':'RIVAL DEFEATED'}</span><div class="defeated-art rival rival-${state.round}" aria-hidden="true"></div><h1>${esc(foe.name)} yields.</h1><p>One victory. One prize. What will become part of your story?</p></div>${replaceMode?`<div class="reward-choices replace-grid"><h2>Replace one Echo with ${esc(move.name)}</h2>${state.moves.map(id=>`<button class="reward-card echo" data-replace="${id}"><strong>${esc(MOVES[id].name)}</strong><p>${esc(MOVES[id].desc)}</p><span>Replace this Echo</span></button>`).join('')}<button class="quiet" data-do="cancel-replace">Back</button></div>`:`<div class="reward-choices"><button class="reward-card tribute" data-reward="gold"><span class="reward-icon">✦</span><strong>Take the Tribute</strong><b>+${tributeValue(state)} coins</b><p>Buy training and stronger road gear at the caravan.</p></button><button class="reward-card trophy" data-reward="gear"><span class="reward-icon equipment-icon" style="${equipmentStyle(state.round)}" aria-hidden="true"></span><strong>Claim the Trophy</strong><b>${esc(foe.name.split(' ')[0])}'s gear</b><p>A drawn rival-tier piece with a permanent combat upgrade.</p></button><button class="reward-card echo" data-reward="move"><span class="reward-icon">◈</span><strong>Steal the Echo</strong><b>${esc(move.name)}</b><p>${esc(move.desc)}</p></button></div>`}</section>`;}

function caravanScreen(){const equipped=state.gear.find(item=>item.id===state.equipped),gearRound=Number(equipped?.id.split('-').at(-1));return `<section class="caravan"><div class="caravan-art"><span class="chapter-kicker">THE WANDERING CARAVAN</span><h1>Patch the coat. Sharpen the story.</h1><p>You recover 10 health on the road. Spend coins now—or save for Masterwork gear.</p><div class="equipped-trophy">${equipped?`<span class="equipment-icon equipped-icon" style="${equipmentStyle(gearRound)}" aria-hidden="true"></span>`:''}<span>Equipped trophy</span><strong>${esc(equipped?.name||'None yet')}</strong><small>${equipped?.tier||'Defeat a rival and claim their gear.'}</small></div></div><div class="shop-grid">${[['weapon','⚔','Sharpen weapon','Every strike gains +2 damage.',30],['armor','⬡','Reinforce coat','Reduce every incoming hit by 1.',30],['heal','♥','Brew moon tea','Recover 25 health.',20]].map(([id,icon,name,desc,cost])=>`<button class="shop-card" data-buy="${id}" ${state.gold<cost||(id==='heal'&&state.hp===state.maxHp)?'disabled':''}><span>${icon}</span><strong>${name}</strong><p>${desc}</p><b>${cost} coins</b></button>`).join('')}</div><button class="primary" data-do="next">Return to the painted road →</button></section>`;}

function endScreen(){const won=state.stage==='won';return `<section class="story-ending"><span class="chapter-kicker">${won?'THE SECOND LAUREL':'THE ROAD REMEMBERS'}</span><h1>${won?'The Crown heard your name.':'Every fallen heir leaves an Echo.'}</h1><p>${won?'This chapter is complete. New regions, Masters and endings can now grow from this foundation.':'Try a different heir, steal a different power, and change the story.'}</p><div class="end-tally"><b>${won?7:state.round}</b><span>duels cleared</span><b>${state.moves.length}</b><span>Echoes claimed</span><b>${state.gear.length}</b><span>Trophies carried</span></div><button class="primary" data-do="restart">Begin another telling</button></section>`;}

function help(){const dialog=document.createElement('dialog');dialog.innerHTML='<h2>Win their gear. Steal their moves.</h2><p>Read the rival’s next move, then choose your answer. Strike and Crush reach 2 spaces for Suri and 1 space for Miri and Tovin. Leap changes distance. A full Block empowers your next attack; Dodge avoids one hit.</p><p>After every win, choose coins, one piece of rival gear, or their signature Echo. You can carry three Echoes. Masters wait at the end of each region.</p><button class="primary">Back to the story</button>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal();}

app.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button||button.disabled||busy)return;const data=button.dataset;
  if(data.hero){chosenHero=data.hero;render();return;}
  if(data.action){busy=true;button.classList.add('committed');const after=structuredClone(state),events=[];if(!act(after,data.action,events)){busy=false;return;}document.querySelectorAll('[data-action]').forEach(item=>item.disabled=true);try{await director.play(events,state);}catch(error){console.error('Combat playback recovered',error);}finally{state=after;save();busy=false;render();if(state.stage!=='battle')tone(true);}return;}
  if(data.reward){if(data.reward==='move'&&state.moves.length>=3)replaceMode=true;else reward(state,data.reward);save();render();return;}
  if(data.replace){reward(state,'move',data.replace);replaceMode=false;save();render();return;}
  if(data.buy){buy(state,data.buy);save();render();return;}
  if(data.do==='choose'){screen='choose';render();return;}
  if(data.do==='begin'){const name=document.querySelector('#name').value.trim()||HEROES[chosenHero].name.split(' ')[0];state=newRun(name,chosenHero);state.stage='map';screen='game';save();render();return;}
  if(data.do==='fight'){enterBattle(state);save();render();return;}
  if(data.do==='resume'){state=structuredClone(saved);migrate(state);screen='game';render();return;}
  if(data.do==='restart'){state=null;saved=null;chosenHero='miri';screen='choose';render();return;}
  if(data.do==='exit'||data.do==='home'){if(state)save();state=null;screen='start';render();return;}
  if(data.do==='next'){next(state);state.stage='map';save();render();return;}
  if(data.do==='cancel-replace'){replaceMode=false;render();return;}
  if(data.do==='sound'){sound=!sound;if(sound)tone();render();return;}
  if(data.do==='help'){help();}
});

for(const type of ['pointerover','focusin'])app.addEventListener(type,event=>{const button=event.target.closest('[data-preview]');if(button&&!busy){const preview=document.querySelector('#move-preview');if(preview)preview.textContent=button.dataset.preview;}});
document.addEventListener('keydown',event=>{if(event.target.matches('input')||document.querySelector('dialog[open]')||!state||state.stage!=='battle'||event.repeat)return;const number=Number(event.key);if(number>=1&&number<=7)document.querySelectorAll('[data-action]')[number-1]?.click();});

render();
